function highlightServiceCard(index, btnEl) {
  // Update button active styles
  document.querySelectorAll('.svc-filter-pill').forEach(btn => {
    btn.className = 'svc-filter-pill px-4 py-2 rounded-full font-label-nav text-sm font-semibold transition-all duration-200 cursor-pointer bg-white text-neutral-800 border border-neutral-300 hover:border-secondary-container hover:text-primary shadow-xs flex items-center gap-1.5';
  });
  if (btnEl) {
    btnEl.className = 'svc-filter-pill px-4 py-2 rounded-full font-label-nav text-sm font-semibold transition-all duration-200 cursor-pointer bg-secondary-container text-on-primary shadow-sm flex items-center gap-1.5';
  }

  const carousel = document.getElementById('services-carousel');
  if (!carousel) return;
  const track = carousel.querySelector('.infinite-cards-track') || carousel;
  const cards = carousel.querySelectorAll('.shrink-0');
  if (!cards || !cards.length) return;

  // Determine target cards based on menu selection
  // 0: Hot Stamping Emas & Foil (Card 0 Hot Stamp)
  // 1: Spot UV Kilap & Taktil (Card 1 Spot UV)
  // 2: Laminasi Doff Velvet (Card 2 Laminating, Card 3 Window)
  // 5: Pond Die-Cut Presisi (Card 5 Pond, Card 7 Emboss)
  // 4: Cast & Cure Hologram (Card 4 Cast and Cure)
  // 'all': Semua Layanan
  let targetIndices = [];
  if (index === 'all') {
    targetIndices = Array.from({ length: cards.length }, (_, i) => i);
  } else if (index === 0 || index === '0' || index === 'hotstamp') {
    targetIndices = [0];
  } else if (index === 1 || index === '1' || index === 'spotuv') {
    targetIndices = [1];
  } else if (index === 2 || index === '2' || index === 'laminating') {
    targetIndices = [2, 3];
  } else if (index === 5 || index === '5' || index === 'pond') {
    targetIndices = [5, 7];
  } else if (index === 4 || index === '4' || index === 'castcure') {
    targetIndices = [4];
  } else if (typeof index === 'number') {
    targetIndices = [index];
  } else {
    targetIndices = Array.from({ length: cards.length }, (_, i) => i);
  }

  // Filter cards: show only target cards
  let visibleCount = 0;
  cards.forEach((card, idx) => {
    if (targetIndices.includes(idx)) {
      card.style.setProperty('display', 'flex', 'important');
      card.style.setProperty('opacity', '1', 'important');
      card.style.setProperty('transform', 'none', 'important');
      card.style.setProperty('animation', 'none', 'important');
      visibleCount++;
    } else {
      card.style.setProperty('display', 'none', 'important');
    }
  });

  // Reset scroll to start
  carousel.scrollTo({ left: 0, behavior: 'instant' });

  // If visible cards are 3 or less (1x3 grid or less): DO NOT LOOP AT ALL
  if (visibleCount <= 3) {
    if (track) {
      track.style.setProperty('animation', 'none', 'important');
      track.style.setProperty('transform', 'none', 'important');
      track.style.setProperty('width', '100%', 'important');
      track.style.setProperty('display', 'grid', 'important');
      track.style.setProperty('grid-template-columns', 'repeat(auto-fit, minmax(320px, 390px))', 'important');
      track.style.setProperty('gap', '1.5rem', 'important');
      track.style.setProperty('justify-content', 'flex-start', 'important');
    }
    carousel.style.setProperty('overflow-x', 'visible', 'important');
    carousel.style.cursor = 'default';
  } else {
    // If more than 3 cards (Semua Layanan): resume auto-looping
    if (track) {
      track.style.setProperty('animation', 'seamlessLoop 90s linear infinite', 'important');
      track.style.setProperty('transform', 'translateX(0)', 'important');
      track.style.setProperty('width', 'max-content', 'important');
      track.style.setProperty('display', 'flex', 'important');
      track.style.setProperty('flex-wrap', 'nowrap', 'important');
      track.style.setProperty('gap', '1.5rem', 'important');
    }
    carousel.style.setProperty('overflow-x', 'auto', 'important');
    carousel.style.cursor = 'grab';
  }
}
window.highlightServiceCard = highlightServiceCard;
setTimeout(() => {
  if (typeof window.highlightServiceCard === 'function') {
    window.highlightServiceCard('all');
  }
}, 50);


